import{_ as t,o,c as e,a2 as r}from"./chunks/framework.A5mep7Fe.js";const d=JSON.parse('{"title":"☕ 02 · Java（AI 平台后端主力）","description":"","frontmatter":{},"headers":[],"relativePath":"06-开发岗-编程语言与工程/02-Java.md","filePath":"06-开发岗-编程语言与工程/02-Java.md","lastUpdated":1786806808000}'),n={name:"06-开发岗-编程语言与工程/02-Java.md"};function l(i,a,s,p,c,h){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="☕-02-·-java-ai-平台后端主力" tabindex="-1">☕ 02 · Java（AI 平台后端主力） <a class="header-anchor" href="#☕-02-·-java-ai-平台后端主力" aria-label="Permalink to &quot;☕ 02 · Java（AI 平台后端主力）&quot;">​</a></h1><blockquote><p>很多 AI 公司的「平台/中台/业务后端」用 Java（Spring 生态成熟、稳定、招人易）。AI 应用 Java 岗需求大。</p></blockquote><hr><h2 id="一、核心考点" tabindex="-1">一、核心考点 <a class="header-anchor" href="#一、核心考点" aria-label="Permalink to &quot;一、核心考点&quot;">​</a></h2><ul><li><strong>JVM 内存模型与 GC</strong>：堆/栈/方法区；GC 算法（G1/ZGC）；调优（OOM 排查、停顿优化）。</li><li><strong>并发</strong>：synchronized、volatile、JUC（线程池、锁、并发容器）、线程安全集合。</li><li><strong>JMM 与可见性</strong>：happens-before、指令重排。</li><li><strong>集合框架</strong>：HashMap 原理（红黑树）、ConcurrentHashMap。</li><li><strong>JVM 调优</strong>：内存参数、GC 日志、火焰图。</li><li><strong>Spring 生态</strong>：IoC/AOP、Spring Boot、事务、MyBatis。</li></ul><h2 id="二、ai-场景结合点" tabindex="-1">二、AI 场景结合点 <a class="header-anchor" href="#二、ai-场景结合点" aria-label="Permalink to &quot;二、AI 场景结合点&quot;">​</a></h2><ul><li><strong>AI 平台后端</strong>：模型管理、Prompt 模板、评测任务调度、标注系统。</li><li><strong>推理服务网关</strong>：封装 LLM API、限流、缓存、成本统计、流式转发（SSE/WebSocket）。</li><li><strong>RAG 后端</strong>：文档 ETL、向量检索编排、权限隔离。</li><li>框架：Spring AI（官方 AI 集成）、LangChain4j。</li></ul><h2 id="三、高频追问" tabindex="-1">三、高频追问 <a class="header-anchor" href="#三、高频追问" aria-label="Permalink to &quot;三、高频追问&quot;">​</a></h2><p><strong>Q1：HashMap 线程安全吗？并发怎么办？</strong></p><blockquote><p>不安全。并发用 ConcurrentHashMap（分段/CAS + synchronized 细粒度锁）或 Collections.synchronizedMap。</p></blockquote><p><strong>Q2：G1 和 ZGC 区别？</strong></p><blockquote><p>G1 分区域、可预测停顿；ZGC 超低停顿（&lt;10ms）、大堆友好，适合对延迟敏感的 AI 服务。</p></blockquote><p><strong>Q3：Java 怎么做流式 LLM 输出？</strong></p><blockquote><p>用 SSE（Server-Sent Events）或 WebSocket 把 token 实时推前端；后端用 WebClient 等响应式 client 消费上游流式响应并转发。</p></blockquote><hr><p>➡️ 下一步：<a href="./03-C-Cpp">03-C-Cpp</a></p>',16)])])}const u=t(n,[["render",l]]);export{d as __pageData,u as default};
